import json
c = json.load(open('/work/workspace/deliverable/claims.json'))
errs = []
req = {"claim":str,"theory":str,"direct_or_derivative":str,"survives_waiver":bool,"limitations":dict,"strength":str,"remedy":str}
for i,cl in enumerate(c):
    for k,t in req.items():
        if k not in cl or not isinstance(cl[k],t): errs.append(f"claim {i}: bad/missing {k}")
    if cl.get("theory") not in ("fiduciary","implied_covenant","express_contract","other"): errs.append(f"claim {i}: bad theory {cl.get('theory')}")
    if cl.get("strength") not in ("low","medium","high"): errs.append(f"claim {i}: bad strength {cl.get('strength')}")
    lim = cl.get("limitations",{})
    for k in ("accrual","barred_portion","tolling_argument"):
        if k not in lim: errs.append(f"claim {i}: limitations missing {k}")
    if not isinstance(lim.get("barred_portion"),(int,float)): errs.append(f"claim {i}: barred_portion not numeric")
print("claims.json:", len(c), "claims;", "VALID" if not errs else errs)
v = json.load(open('/work/workspace/deliverable/valuation_gap.json'))
vreq = {"book_value_offer":(int,float),"independent_indication_18pct":(int,float),"independent_indication_6_1pct":(int,float),"dilution_valid":bool,"why":str}
VERR = [k for k,t in vreq.items() if k not in v or not isinstance(v[k],t)]
print("valuation_gap.json keys:", sorted(v.keys()))
print("valuation_gap.json:", "VALID" if not VERR else VERR)
print("values:", v["book_value_offer"], v["independent_indication_18pct"], v["independent_indication_6_1pct"], v["dilution_valid"])
EOF

